<h1 class="h">Přijaté faktury</h1><div class="sub">Závazky oddělené od běžných výdajů. Úhradu zatím evidujete ručně; bankovní párování lze doplnit.</div><div class="card" style="margin-top:16px"><h3>Nová přijatá faktura</h3><form class="form" method="post" action="/received-invoices/save"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Dodavatel</label><input name="supplier_name" required></div><div class="field"><label>IČO</label><input name="supplier_ico"></div></div><div class="row"><div class="field"><label>Číslo dokladu</label><input name="document_number"></div><div class="field"><label>Variabilní symbol</label><input name="variable_symbol"></div></div><div class="row"><div class="field"><label>Vystaveno</label><input type="date" name="issue_date" value="<?=date('Y-m-d')?>"></div><div class="field"><label>Splatnost</label><input type="date" name="due_date"></div></div><div class="row"><div class="field"><label>Celkem</label><input type="number" step="0.01" name="amount" required></div><div class="field"><label>DPH</label><input type="number" step="0.01" name="vat_amount" value="0"></div></div><div class="row"><div class="field"><label>Měna</label><input name="currency" value="CZK" maxlength="3"></div><div class="field"><label>Poznámka</label><input name="note"></div></div><button class="btn primary">Uložit</button></form></div><div class="card" style="margin-top:16px"><h3>Seznam závazků</h3><div class="tablewrap"><table class="table"><tr><th>Dodavatel</th><th>Doklad</th><th>Splatnost</th><th>Částka</th><th>Stav</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=App\Core\View::e($r['supplier_name'])?></td><td><?=App\Core\View::e($r['document_number'])?></td><td><?=App\Core\View::e($r['due_date'])?></td><td><?=number_format((float)$r['amount'],2,',',' ')?> <?=App\Core\View::e($r['currency'])?></td><td><?=App\Core\View::e($r['payment_status'])?></td><td><?php if($r['payment_status']!=='paid'):?><form method="post" action="/received-invoices/<?=$r['id']?>/paid"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><button class="btn">Označit uhrazeno</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>